using System.Text.Json;

namespace BatchRenameStudio.Core;

public enum ApplyTo
{
    Name,
    NameAndExtension,
}

public enum SortMode
{
    Name,
    Created,
    Modified,
}

public enum InsertPosition
{
    Prefix,
    Suffix,
    Index,
}

public enum AffixPosition
{
    Prefix,
    Suffix,
}

public enum CaseMode
{
    Upper,
    Lower,
    Title,
}

public enum ExtensionMode
{
    Lower,
    Upper,
    Set,
}

/// <summary>Thrown when a rules document cannot be understood. Fatal for both CLI and GUI.</summary>
public sealed class RuleConfigException : Exception
{
    public RuleConfigException(string message) : base(message) { }
}

/// <summary>One transformation applied to the target string of every file.</summary>
public abstract class RuleStep
{
    public abstract string Op { get; }

    /// <summary>Short human readable form shown in the rule list of the GUI.</summary>
    public abstract string Describe();

    public abstract void Write(Utf8JsonWriter w);

    public abstract RuleStep Clone();
}

public sealed class ReplaceStep : RuleStep
{
    public string Find { get; set; } = string.Empty;
    public string ReplaceWith { get; set; } = string.Empty;
    public bool Regex { get; set; }
    public bool IgnoreCase { get; set; }

    public override string Op => "replace";

    public override string Describe()
    {
        var flags = (Regex ? " regex" : string.Empty) + (IgnoreCase ? " ignore-case" : string.Empty);
        return $"replace \"{Find}\" -> \"{ReplaceWith}\"{flags}";
    }

    public override void Write(Utf8JsonWriter w)
    {
        w.WriteStartObject();
        w.WriteString("op", Op);
        w.WriteString("find", Find);
        w.WriteString("replaceWith", ReplaceWith);
        w.WriteBoolean("regex", Regex);
        w.WriteBoolean("ignoreCase", IgnoreCase);
        w.WriteEndObject();
    }

    public override RuleStep Clone() => new ReplaceStep
    {
        Find = Find,
        ReplaceWith = ReplaceWith,
        Regex = Regex,
        IgnoreCase = IgnoreCase,
    };
}

public sealed class InsertStep : RuleStep
{
    public string Text { get; set; } = string.Empty;
    public InsertPosition Position { get; set; } = InsertPosition.Prefix;
    public int Index { get; set; }

    public override string Op => "insert";

    public override string Describe() => Position == InsertPosition.Index
        ? $"insert \"{Text}\" at index {Index}"
        : $"insert \"{Text}\" as {Position.ToString().ToLowerInvariant()}";

    public override void Write(Utf8JsonWriter w)
    {
        w.WriteStartObject();
        w.WriteString("op", Op);
        w.WriteString("text", Text);
        w.WriteString("position", Position switch
        {
            InsertPosition.Prefix => "prefix",
            InsertPosition.Suffix => "suffix",
            _ => "index",
        });
        w.WriteNumber("index", Index);
        w.WriteEndObject();
    }

    public override RuleStep Clone() => new InsertStep { Text = Text, Position = Position, Index = Index };
}

public sealed class RemoveStep : RuleStep
{
    public int From { get; set; }
    public int Count { get; set; }

    public override string Op => "remove";

    public override string Describe() => $"remove {Count} char(s) from index {From}";

    public override void Write(Utf8JsonWriter w)
    {
        w.WriteStartObject();
        w.WriteString("op", Op);
        w.WriteNumber("from", From);
        w.WriteNumber("count", Count);
        w.WriteEndObject();
    }

    public override RuleStep Clone() => new RemoveStep { From = From, Count = Count };
}

public sealed class SequenceStep : RuleStep
{
    public string Pattern { get; set; } = "{n:000}_";
    public int Start { get; set; } = 1;
    public int Step { get; set; } = 1;
    public AffixPosition Position { get; set; } = AffixPosition.Prefix;

    public override string Op => "sequence";

    public override string Describe() =>
        $"sequence \"{Pattern}\" start {Start} step {Step} as {Position.ToString().ToLowerInvariant()}";

    public override void Write(Utf8JsonWriter w)
    {
        w.WriteStartObject();
        w.WriteString("op", Op);
        w.WriteString("pattern", Pattern);
        w.WriteNumber("start", Start);
        w.WriteNumber("step", Step);
        w.WriteString("position", Position == AffixPosition.Prefix ? "prefix" : "suffix");
        w.WriteEndObject();
    }

    public override RuleStep Clone() => new SequenceStep
    {
        Pattern = Pattern,
        Start = Start,
        Step = Step,
        Position = Position,
    };
}

public sealed class CaseStep : RuleStep
{
    public CaseMode Mode { get; set; } = CaseMode.Lower;

    public override string Op => "case";

    public override string Describe() => $"case {Mode.ToString().ToLowerInvariant()}";

    public override void Write(Utf8JsonWriter w)
    {
        w.WriteStartObject();
        w.WriteString("op", Op);
        w.WriteString("mode", Mode.ToString().ToLowerInvariant());
        w.WriteEndObject();
    }

    public override RuleStep Clone() => new CaseStep { Mode = Mode };
}

public sealed class ExtensionStep : RuleStep
{
    public ExtensionMode Mode { get; set; } = ExtensionMode.Lower;
    public string Value { get; set; } = string.Empty;

    public override string Op => "extension";

    public override string Describe() => Mode == ExtensionMode.Set
        ? $"extension set \"{Value}\""
        : $"extension {Mode.ToString().ToLowerInvariant()}";

    public override void Write(Utf8JsonWriter w)
    {
        w.WriteStartObject();
        w.WriteString("op", Op);
        w.WriteString("mode", Mode.ToString().ToLowerInvariant());
        w.WriteString("value", Value);
        w.WriteEndObject();
    }

    public override RuleStep Clone() => new ExtensionStep { Mode = Mode, Value = Value };
}

/// <summary>A complete rule document: what to operate on, in which order, and the step chain.</summary>
public sealed class RuleSet
{
    public ApplyTo ApplyTo { get; set; } = ApplyTo.Name;
    public SortMode Sort { get; set; } = SortMode.Name;
    public List<RuleStep> Steps { get; } = new();

    public RuleSet Clone()
    {
        var copy = new RuleSet { ApplyTo = ApplyTo, Sort = Sort };
        foreach (var s in Steps)
        {
            copy.Steps.Add(s.Clone());
        }

        return copy;
    }
}

