using System.Text;
using System.Text.Json;

namespace BatchRenameStudio.Core;

/// <summary>Reads and writes the rules.json document described by the tool contract.</summary>
public static class RuleSetIo
{
    private static readonly JsonDocumentOptions DocOptions = new()
    {
        AllowTrailingCommas = true,
        CommentHandling = JsonCommentHandling.Skip,
    };

    public static RuleSet Load(string path)
    {
        string text;
        try
        {
            text = File.ReadAllText(path, Encoding.UTF8);
        }
        catch (Exception ex)
        {
            throw new RuleConfigException($"cannot read rules file '{path}': {ex.Message}");
        }

        return Parse(text);
    }

    public static RuleSet Parse(string json)
    {
        JsonDocument doc;
        try
        {
            doc = JsonDocument.Parse(json, DocOptions);
        }
        catch (JsonException ex)
        {
            throw new RuleConfigException($"rules file is not valid JSON: {ex.Message}");
        }

        using (doc)
        {
            var root = doc.RootElement;
            if (root.ValueKind != JsonValueKind.Object)
            {
                throw new RuleConfigException("rules file must contain a JSON object at the root");
            }

            var set = new RuleSet
            {
                ApplyTo = ParseApplyTo(GetString(root, "applyTo")),
                Sort = ParseSort(GetString(root, "sort")),
            };

            if (root.TryGetProperty("steps", out var steps))
            {
                if (steps.ValueKind != JsonValueKind.Array)
                {
                    throw new RuleConfigException("'steps' must be an array");
                }

                var i = 0;
                foreach (var step in steps.EnumerateArray())
                {
                    set.Steps.Add(ParseStep(step, i));
                    i++;
                }
            }

            return set;
        }
    }

    public static string Serialize(RuleSet set)
    {
        var buffer = new MemoryStream();
        using (var w = new Utf8JsonWriter(buffer, new JsonWriterOptions { Indented = true }))
        {
            w.WriteStartObject();
            w.WriteString("applyTo", set.ApplyTo == ApplyTo.Name ? "name" : "nameAndExtension");
            w.WriteString("sort", set.Sort switch
            {
                SortMode.Created => "created",
                SortMode.Modified => "modified",
                _ => "name",
            });
            w.WriteStartArray("steps");
            foreach (var step in set.Steps)
            {
                step.Write(w);
            }

            w.WriteEndArray();
            w.WriteEndObject();
        }

        return Encoding.UTF8.GetString(buffer.ToArray());
    }

    public static void Save(string path, RuleSet set)
    {
        // UTF-8 without BOM, matching the plan output convention.
        File.WriteAllText(path, Serialize(set), new UTF8Encoding(false));
    }

    private static RuleStep ParseStep(JsonElement e, int index)
    {
        if (e.ValueKind != JsonValueKind.Object)
        {
            throw new RuleConfigException($"steps[{index}] must be an object");
        }

        var op = (GetString(e, "op") ?? string.Empty).Trim();
        switch (op.ToLowerInvariant())
        {
            case "replace":
                return new ReplaceStep
                {
                    Find = GetString(e, "find") ?? string.Empty,
                    ReplaceWith = GetString(e, "replaceWith") ?? string.Empty,
                    Regex = GetBool(e, "regex", false),
                    IgnoreCase = GetBool(e, "ignoreCase", false),
                };

            case "insert":
                return new InsertStep
                {
                    Text = GetString(e, "text") ?? string.Empty,
                    Position = (GetString(e, "position") ?? "prefix").ToLowerInvariant() switch
                    {
                        "prefix" => InsertPosition.Prefix,
                        "suffix" => InsertPosition.Suffix,
                        "index" => InsertPosition.Index,
                        var other => throw new RuleConfigException(
                            $"steps[{index}]: unknown insert position '{other}'"),
                    },
                    Index = GetInt(e, "index", 0),
                };

            case "remove":
                return new RemoveStep
                {
                    From = GetInt(e, "from", 0),
                    Count = GetInt(e, "count", 0),
                };

            case "sequence":
                return new SequenceStep
                {
                    Pattern = GetString(e, "pattern") ?? string.Empty,
                    Start = GetInt(e, "start", 1),
                    Step = GetInt(e, "step", 1),
                    Position = (GetString(e, "position") ?? "prefix").ToLowerInvariant() switch
                    {
                        "prefix" => AffixPosition.Prefix,
                        "suffix" => AffixPosition.Suffix,
                        var other => throw new RuleConfigException(
                            $"steps[{index}]: unknown sequence position '{other}'"),
                    },
                };

            case "case":
                return new CaseStep
                {
                    Mode = (GetString(e, "mode") ?? string.Empty).ToLowerInvariant() switch
                    {
                        "upper" => CaseMode.Upper,
                        "lower" => CaseMode.Lower,
                        "title" => CaseMode.Title,
                        var other => throw new RuleConfigException(
                            $"steps[{index}]: unknown case mode '{other}'"),
                    },
                };

            case "extension":
                return new ExtensionStep
                {
                    Mode = (GetString(e, "mode") ?? string.Empty).ToLowerInvariant() switch
                    {
                        "lower" => ExtensionMode.Lower,
                        "upper" => ExtensionMode.Upper,
                        "set" => ExtensionMode.Set,
                        var other => throw new RuleConfigException(
                            $"steps[{index}]: unknown extension mode '{other}'"),
                    },
                    Value = GetString(e, "value") ?? string.Empty,
                };

            default:
                throw new RuleConfigException($"steps[{index}]: unknown op '{op}'");
        }
    }

    private static ApplyTo ParseApplyTo(string? raw) => (raw ?? "name") switch
    {
        "name" => ApplyTo.Name,
        "nameAndExtension" => ApplyTo.NameAndExtension,
        var other => other.Equals("nameAndExtension", StringComparison.OrdinalIgnoreCase)
            ? ApplyTo.NameAndExtension
            : other.Equals("name", StringComparison.OrdinalIgnoreCase)
                ? ApplyTo.Name
                : throw new RuleConfigException($"unknown applyTo value '{other}'"),
    };

    private static SortMode ParseSort(string? raw) => (raw ?? "name").ToLowerInvariant() switch
    {
        "name" => SortMode.Name,
        "created" => SortMode.Created,
        "modified" => SortMode.Modified,
        var other => throw new RuleConfigException($"unknown sort value '{other}'"),
    };

    private static string? GetString(JsonElement obj, string name)
    {
        if (!obj.TryGetProperty(name, out var v))
        {
            return null;
        }

        return v.ValueKind switch
        {
            JsonValueKind.String => v.GetString(),
            JsonValueKind.Null => null,
            JsonValueKind.Number => v.ToString(),
            _ => throw new RuleConfigException($"'{name}' must be a string"),
        };
    }

    private static bool GetBool(JsonElement obj, string name, bool fallback)
    {
        if (!obj.TryGetProperty(name, out var v))
        {
            return fallback;
        }

        return v.ValueKind switch
        {
            JsonValueKind.True => true,
            JsonValueKind.False => false,
            JsonValueKind.Null => fallback,
            _ => throw new RuleConfigException($"'{name}' must be a boolean"),
        };
    }

    private static int GetInt(JsonElement obj, string name, int fallback)
    {
        if (!obj.TryGetProperty(name, out var v))
        {
            return fallback;
        }

        if (v.ValueKind == JsonValueKind.Null)
        {
            return fallback;
        }

        if (v.ValueKind == JsonValueKind.Number && v.TryGetInt32(out var i))
        {
            return i;
        }

        if (v.ValueKind == JsonValueKind.String && int.TryParse(v.GetString(), out var parsed))
        {
            return parsed;
        }

        throw new RuleConfigException($"'{name}' must be an integer");
    }
}

