using System.Globalization;
using System.Text;
using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core;

/// <summary>base/extension decomposition of a file name (the extension never carries the dot).</summary>
public readonly record struct NameParts(string Base, string Ext)
{
    /// <summary>
    /// Contract rule 2: split at the LAST '.' when its index is &gt; 0, otherwise the whole name is the base.
    /// </summary>
    public static NameParts Split(string name)
    {
        var dot = name.LastIndexOf('.');
        return dot > 0
            ? new NameParts(name[..dot], name[(dot + 1)..])
            : new NameParts(name, string.Empty);
    }

    public string Join() => Ext.Length == 0 ? Base : Base + "." + Ext;
}

/// <summary>
/// Applies a <see cref="RuleSet"/> to a single file name. The engine is pure: no file system access,
/// so the GUI preview and the headless planner cannot drift apart.
/// </summary>
public static class RuleEngine
{
    private static readonly Regex SequenceToken = new(@"\{n:(0+)\}", RegexOptions.CultureInvariant);

    /// <summary>
    /// Produces the proposed file name.
    /// </summary>
    /// <param name="originalName">The file name including its extension.</param>
    /// <param name="rules">The step chain.</param>
    /// <param name="ordinal">0-based position of the file in processing order (drives <c>sequence</c>).</param>
    public static string Apply(string originalName, RuleSet rules, int ordinal)
    {
        var whole = rules.ApplyTo == ApplyTo.NameAndExtension;
        var parts = NameParts.Split(originalName);

        // In "whole" mode the target string is the entire file name and there is no separate ext slot;
        // an extension step re-splits the current target on demand (contract rule 12).
        var target = whole ? originalName : parts.Base;
        var ext = whole ? string.Empty : parts.Ext;

        foreach (var step in rules.Steps)
        {
            if (step is ExtensionStep extStep)
            {
                if (whole)
                {
                    var inner = NameParts.Split(target);
                    var newExt = ApplyExtension(inner.Ext, extStep);
                    target = new NameParts(inner.Base, newExt).Join();
                }
                else
                {
                    ext = ApplyExtension(ext, extStep);
                }

                continue;
            }

            target = ApplyToTarget(target, step, ordinal);
        }

        return whole ? target : new NameParts(target, ext).Join();
    }

    private static string ApplyToTarget(string s, RuleStep step, int ordinal) => step switch
    {
        ReplaceStep r => ApplyReplace(s, r),
        InsertStep i => ApplyInsert(s, i),
        RemoveStep r => ApplyRemove(s, r),
        SequenceStep q => ApplySequence(s, q, ordinal),
        CaseStep c => ApplyCase(s, c.Mode),
        _ => s,
    };

    private static string ApplyReplace(string s, ReplaceStep step)
    {
        if (step.Find.Length == 0)
        {
            // An empty literal pattern has no well-defined "all occurrences"; treat it as a no-op.
            return step.Regex ? ReplaceRegex(s, step) : s;
        }

        return step.Regex ? ReplaceRegex(s, step) : ReplaceLiteral(s, step);
    }

    private static string ReplaceRegex(string s, ReplaceStep step)
    {
        var options = RegexOptions.CultureInvariant;
        if (step.IgnoreCase)
        {
            options |= RegexOptions.IgnoreCase;
        }

        try
        {
            return Regex.Replace(s, step.Find, step.ReplaceWith, options);
        }
        catch (ArgumentException ex)
        {
            throw new RuleConfigException($"invalid regular expression '{step.Find}': {ex.Message}");
        }
    }

    private static string ReplaceLiteral(string s, ReplaceStep step)
    {
        var comparison = step.IgnoreCase ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;
        var sb = new StringBuilder();
        var pos = 0;
        while (true)
        {
            var hit = s.IndexOf(step.Find, pos, comparison);
            if (hit < 0)
            {
                sb.Append(s, pos, s.Length - pos);
                return sb.ToString();
            }

            sb.Append(s, pos, hit - pos);
            sb.Append(step.ReplaceWith);
            pos = hit + step.Find.Length;
        }
    }

    private static string ApplyInsert(string s, InsertStep step) => step.Position switch
    {
        InsertPosition.Prefix => step.Text + s,
        InsertPosition.Suffix => s + step.Text,
        _ => s.Insert(Math.Clamp(step.Index, 0, s.Length), step.Text),
    };

    private static string ApplyRemove(string s, RemoveStep step)
    {
        var from = Math.Clamp(step.From, 0, s.Length);
        var count = Math.Clamp(step.Count, 0, s.Length - from);
        return count == 0 ? s : s.Remove(from, count);
    }

    private static string ApplySequence(string s, SequenceStep step, int ordinal)
    {
        var value = step.Start + (long)step.Step * ordinal;
        var rendered = RenderSequence(step.Pattern, value);
        return step.Position == AffixPosition.Prefix ? rendered + s : s + rendered;
    }

    /// <summary>Substitutes the single <c>{n:000}</c> token; the zero run gives the pad width.</summary>
    public static string RenderSequence(string pattern, long value)
    {
        var match = SequenceToken.Match(pattern);
        if (!match.Success)
        {
            // No token: the pattern is pure literal text. Keeps a malformed pattern predictable.
            return pattern;
        }

        var width = match.Groups[1].Value.Length;
        var number = value.ToString(new string('0', width), CultureInfo.InvariantCulture);
        return pattern[..match.Index] + number + pattern[(match.Index + match.Length)..];
    }

    private static string ApplyCase(string s, CaseMode mode)
    {
        switch (mode)
        {
            case CaseMode.Upper:
                return s.ToUpperInvariant();
            case CaseMode.Lower:
                return s.ToLowerInvariant();
            default:
                return ToTitle(s);
        }
    }

    /// <summary>
    /// Each maximal run of Unicode letters gets an upper-cased first character and lower-cased rest;
    /// everything else is copied verbatim.
    /// </summary>
    private static string ToTitle(string s)
    {
        var sb = new StringBuilder(s.Length);
        var inRun = false;
        foreach (var ch in s)
        {
            if (char.IsLetter(ch))
            {
                sb.Append(inRun ? char.ToLowerInvariant(ch) : char.ToUpperInvariant(ch));
                inRun = true;
            }
            else
            {
                sb.Append(ch);
                inRun = false;
            }
        }

        return sb.ToString();
    }

    private static string ApplyExtension(string ext, ExtensionStep step) => step.Mode switch
    {
        ExtensionMode.Lower => ext.ToLowerInvariant(),
        ExtensionMode.Upper => ext.ToUpperInvariant(),
        _ => step.Value,
    };
}

