namespace BatchRenameStudio.Core;

public enum PlanStatus
{
    Ok,
    Collision,
    Unchanged,
    Invalid,
}

public static class PlanStatusText
{
    public static string Wire(this PlanStatus s) => s switch
    {
        PlanStatus.Ok => "ok",
        PlanStatus.Collision => "collision",
        PlanStatus.Unchanged => "unchanged",
        _ => "invalid",
    };
}

/// <summary>One planned rename. <see cref="Ordinal"/> is the file's position in processing order.</summary>
public sealed class PlanItem
{
    public required string Original { get; init; }
    public required string Proposed { get; init; }
    public required PlanStatus Status { get; init; }
    public required string Reason { get; init; }
    public required int Ordinal { get; init; }

    /// <summary>Absolute path of the source file; empty for items built from a dry data set.</summary>
    public string FullPath { get; init; } = string.Empty;
}

public sealed class PlanSummary
{
    public int Total { get; init; }
    public int Ok { get; init; }
    public int Collision { get; init; }
    public int Unchanged { get; init; }
    public int Invalid { get; init; }
}

public sealed class RenamePlan
{
    public const int SchemaVersion = 1;

    public required string Directory { get; init; }
    public required IReadOnlyList<PlanItem> Items { get; init; }

    public PlanSummary Summary => new()
    {
        Total = Items.Count,
        Ok = Items.Count(i => i.Status == PlanStatus.Ok),
        Collision = Items.Count(i => i.Status == PlanStatus.Collision),
        Unchanged = Items.Count(i => i.Status == PlanStatus.Unchanged),
        Invalid = Items.Count(i => i.Status == PlanStatus.Invalid),
    };
}

