using System.Text.RegularExpressions;

namespace BatchRenameStudio.Core;

/// <summary>Metadata the planner needs about a source file; kept separate so the planner stays testable.</summary>
public sealed record FileEntry(string Name, string FullPath, DateTime CreatedUtc, DateTime ModifiedUtc);

/// <summary>Builds a <see cref="RenamePlan"/> from a folder (or a pre-collected file list) plus a rule set.</summary>
public static class PlanBuilder
{
    private static readonly char[] IllegalChars = { '<', '>', ':', '"', '/', '\\', '|', '?', '*' };

    private static readonly Regex ReservedDeviceName =
        new(@"^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])$",
            RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);

    public const int MaxNameLength = 255;

    /// <summary>Enumerates the regular files directly inside <paramref name="directory"/> (non-recursive).</summary>
    public static List<FileEntry> Scan(string directory)
    {
        var dir = new DirectoryInfo(directory);
        if (!dir.Exists)
        {
            throw new DirectoryNotFoundException($"directory not found: {directory}");
        }

        var entries = new List<FileEntry>();
        foreach (var f in dir.EnumerateFiles("*", SearchOption.TopDirectoryOnly))
        {
            // EnumerateFiles already excludes directories; guard anyway against odd reparse entries.
            if ((f.Attributes & FileAttributes.Directory) != 0)
            {
                continue;
            }

            entries.Add(new FileEntry(f.Name, f.FullName, f.CreationTimeUtc, f.LastWriteTimeUtc));
        }

        return entries;
    }

    /// <summary>Contract rule 5: ascending by the chosen key, with an ordinal name tiebreak for determinism.</summary>
    public static List<FileEntry> SortEntries(IEnumerable<FileEntry> entries, SortMode sort) => sort switch
    {
        SortMode.Created => entries
            .OrderBy(e => e.CreatedUtc)
            .ThenBy(e => e.Name, StringComparer.Ordinal)
            .ToList(),
        SortMode.Modified => entries
            .OrderBy(e => e.ModifiedUtc)
            .ThenBy(e => e.Name, StringComparer.Ordinal)
            .ToList(),
        _ => entries.OrderBy(e => e.Name, StringComparer.Ordinal).ToList(),
    };

    public static RenamePlan Build(string directory, RuleSet rules)
        => Build(directory, Scan(directory), rules);

    public static RenamePlan Build(string directory, IEnumerable<FileEntry> entries, RuleSet rules)
    {
        var ordered = SortEntries(entries, rules.Sort);

        var proposals = new string[ordered.Count];
        for (var i = 0; i < ordered.Count; i++)
        {
            // The sequence counter advances for every file, whatever its final status.
            proposals[i] = RuleEngine.Apply(ordered[i].Name, rules, i);
        }

        var existing = new HashSet<string>(ordered.Select(e => e.Name), StringComparer.OrdinalIgnoreCase);

        var proposedCounts = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
        foreach (var p in proposals)
        {
            proposedCounts[p] = proposedCounts.TryGetValue(p, out var c) ? c + 1 : 1;
        }

        var items = new List<PlanItem>(ordered.Count);
        for (var i = 0; i < ordered.Count; i++)
        {
            var original = ordered[i].Name;
            var proposed = proposals[i];
            var (status, reason) = Classify(original, proposed, existing, proposedCounts);

            items.Add(new PlanItem
            {
                Original = original,
                Proposed = proposed,
                Status = status,
                Reason = reason,
                Ordinal = i,
                FullPath = ordered[i].FullPath,
            });
        }

        return new RenamePlan { Directory = directory, Items = items };
    }

    /// <summary>Contract rule 13, evaluated in the stated precedence order.</summary>
    private static (PlanStatus Status, string Reason) Classify(
        string original,
        string proposed,
        HashSet<string> existingNames,
        Dictionary<string, int> proposedCounts)
    {
        var invalidReason = InvalidReason(proposed);
        if (invalidReason is not null)
        {
            return (PlanStatus.Invalid, invalidReason);
        }

        var clashesWithExisting = existingNames.Contains(proposed)
                                  && !proposed.Equals(original, StringComparison.OrdinalIgnoreCase);
        var clashesWithSibling = proposedCounts.TryGetValue(proposed, out var count) && count > 1;
        if (clashesWithExisting || clashesWithSibling)
        {
            return (PlanStatus.Collision, clashesWithSibling
                ? "another item proposes the same name"
                : "an existing file already uses this name");
        }

        if (string.Equals(proposed, original, StringComparison.Ordinal))
        {
            return (PlanStatus.Unchanged, "rules produced no change");
        }

        return (PlanStatus.Ok, string.Empty);
    }

    /// <summary>Returns a short reason when the proposed name cannot exist on Windows, otherwise null.</summary>
    public static string? InvalidReason(string proposed)
    {
        if (proposed.Length == 0)
        {
            return "empty name";
        }

        if (proposed.Length > MaxNameLength)
        {
            return $"longer than {MaxNameLength} characters";
        }

        foreach (var ch in proposed)
        {
            if (ch < ' ')
            {
                return "contains a control character";
            }

            if (Array.IndexOf(IllegalChars, ch) >= 0)
            {
                return $"contains illegal character '{ch}'";
            }
        }

        var baseName = NameParts.Split(proposed).Base;
        if (ReservedDeviceName.IsMatch(baseName))
        {
            return $"'{baseName}' is a reserved device name";
        }

        return null;
    }
}

