using System.Text;
using System.Text.Json;

namespace BatchRenameStudio.Core;

/// <summary>Serializes a <see cref="RenamePlan"/> to the contract's plan.json shape.</summary>
public static class PlanWriter
{
    /// <summary>Writes plan.json as UTF-8 without a BOM.</summary>
    public static void WriteFile(string path, RenamePlan plan)
    {
        var full = Path.GetFullPath(path);
        var dir = Path.GetDirectoryName(full);
        if (!string.IsNullOrEmpty(dir))
        {
            Directory.CreateDirectory(dir);
        }

        var bytes = SerializeUtf8(plan);
        File.WriteAllBytes(full, bytes);
    }

    public static byte[] SerializeUtf8(RenamePlan plan)
    {
        using var buffer = new MemoryStream();
        using (var w = new Utf8JsonWriter(buffer, new JsonWriterOptions { Indented = true }))
        {
            var summary = plan.Summary;

            w.WriteStartObject();
            w.WriteNumber("schemaVersion", RenamePlan.SchemaVersion);

            w.WriteStartArray("items");
            foreach (var item in plan.Items)
            {
                w.WriteStartObject();
                w.WriteString("original", item.Original);
                w.WriteString("proposed", item.Proposed);
                w.WriteString("status", item.Status.Wire());
                w.WriteString("reason", item.Reason);
                w.WriteEndObject();
            }

            w.WriteEndArray();

            w.WriteStartObject("summary");
            w.WriteNumber("total", summary.Total);
            w.WriteNumber("ok", summary.Ok);
            w.WriteNumber("collision", summary.Collision);
            w.WriteNumber("unchanged", summary.Unchanged);
            w.WriteNumber("invalid", summary.Invalid);
            w.WriteEndObject();

            w.WriteEndObject();
        }

        return buffer.ToArray();
    }

    public static string SerializeText(RenamePlan plan) => Encoding.UTF8.GetString(SerializeUtf8(plan));
}

