namespace BatchRenameStudio.Core;

/// <summary>A single completed rename, in the form needed to replay it backwards.</summary>
public sealed record RenameOp(string Directory, string From, string To);

/// <summary>One undoable batch.</summary>
public sealed class RenameBatch
{
    public required string Directory { get; init; }
    public required IReadOnlyList<RenameOp> Ops { get; init; }
    public required DateTime PerformedAt { get; init; }

    public string Describe() => $"{Ops.Count} file(s) in {Directory} at {PerformedAt:HH:mm:ss}";
}

public sealed class RenameOutcome
{
    public List<RenameOp> Applied { get; } = new();
    public List<string> Errors { get; } = new();
    public bool Success => Errors.Count == 0;
}

/// <summary>
/// Performs the renames of a plan. Every batch goes through a temporary-name phase so that swaps and
/// rotations (a→b, b→a) succeed, and so a partial failure can be rolled back.
/// </summary>
public static class RenameExecutor
{
    private const string TempMarker = ".brs-tmp-";

    /// <summary>Renames every item whose status is <c>ok</c>. Other statuses are skipped untouched.</summary>
    public static RenameOutcome Execute(RenamePlan plan)
    {
        var pairs = plan.Items
            .Where(i => i.Status == PlanStatus.Ok)
            .Select(i => new RenameOp(plan.Directory, i.Original, i.Proposed))
            .ToList();

        return Execute(plan.Directory, pairs);
    }

    /// <summary>Replays a completed batch backwards.</summary>
    public static RenameOutcome Undo(RenameBatch batch)
    {
        var reversed = batch.Ops
            .AsEnumerable()
            .Reverse()
            .Select(op => new RenameOp(op.Directory, op.To, op.From))
            .ToList();

        return Execute(batch.Directory, reversed);
    }

    public static RenameOutcome Execute(string directory, IReadOnlyList<RenameOp> ops)
    {
        var outcome = new RenameOutcome();
        if (ops.Count == 0)
        {
            return outcome;
        }

        var staged = new List<(string TempPath, string FinalPath, RenameOp Op)>();

        // Phase 1 — move every source out of the way under a unique temporary name.
        for (var i = 0; i < ops.Count; i++)
        {
            var op = ops[i];
            var source = Path.Combine(directory, op.From);
            var temp = Path.Combine(directory, TempMarker + i.ToString("D6") + "-" + Guid.NewGuid().ToString("N")[..8]);
            try
            {
                File.Move(source, temp);
                staged.Add((temp, Path.Combine(directory, op.To), op));
            }
            catch (Exception ex)
            {
                outcome.Errors.Add($"{op.From}: {ex.Message}");
                RollbackStaged(staged, outcome);
                return outcome;
            }
        }

        // Phase 2 — settle each temporary file on its final name.
        var settled = new List<(string FinalPath, string TempPath, RenameOp Op)>();
        foreach (var (temp, final, op) in staged)
        {
            try
            {
                File.Move(temp, final);
                settled.Add((final, temp, op));
                outcome.Applied.Add(op);
            }
            catch (Exception ex)
            {
                outcome.Errors.Add($"{op.From} -> {op.To}: {ex.Message}");
                outcome.Applied.Clear();

                // Put the already-settled files back into their temp names, then restore everything.
                foreach (var (doneFinal, doneTemp, _) in settled)
                {
                    TryMove(doneFinal, doneTemp, outcome);
                }

                RollbackStaged(staged, outcome);
                return outcome;
            }
        }

        return outcome;
    }

    private static void RollbackStaged(
        List<(string TempPath, string FinalPath, RenameOp Op)> staged,
        RenameOutcome outcome)
    {
        foreach (var (temp, _, op) in staged)
        {
            TryMove(temp, Path.Combine(op.Directory, op.From), outcome);
        }
    }

    private static void TryMove(string from, string to, RenameOutcome outcome)
    {
        try
        {
            if (File.Exists(from))
            {
                File.Move(from, to);
            }
        }
        catch (Exception ex)
        {
            outcome.Errors.Add($"rollback failed for '{from}': {ex.Message}");
        }
    }
}

