namespace BatchRenameStudio.Cli;

/// <summary>
/// The app is a WinExe, so it owns no console. When it is started from a terminal we attach to the
/// parent console; when stdout/stderr are redirected we leave the existing handles alone.
/// </summary>
public static class ConsoleBridge
{
    private const int AttachParentProcess = -1;

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern bool AttachConsole(int processId);

    public static void Attach()
    {
        var needStdout = !Console.IsOutputRedirected;
        var needStderr = !Console.IsErrorRedirected;
        if (!needStdout && !needStderr)
        {
            return;
        }

        if (!AttachConsole(AttachParentProcess))
        {
            return;
        }

        if (needStdout)
        {
            var stdout = new StreamWriter(Console.OpenStandardOutput(), new UTF8Encoding(false))
            {
                AutoFlush = true,
            };
            Console.SetOut(stdout);
        }

        if (needStderr)
        {
            var stderr = new StreamWriter(Console.OpenStandardError(), new UTF8Encoding(false))
            {
                AutoFlush = true,
            };
            Console.SetError(stderr);
        }
    }
}

