using System.Globalization;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Cli;

public static class ExitCodes
{
    public const int Success = 0;
    public const int Usage = 2;
    public const int BadRules = 3;
    public const int IoError = 4;
}

/// <summary>
/// Implements the fixed contract:
/// <c>BatchRenameStudio.exe --plan --dir &lt;folder&gt; --rules &lt;rules.json&gt; --out &lt;plan.json&gt;</c>.
/// Never touches the files it plans over.
/// </summary>
public static class HeadlessRunner
{
    public const string Usage =
        "usage: BatchRenameStudio.exe --plan --dir <folder> --rules <rules.json> --out <plan.json>";

    public static int Run(string[] args)
    {
        string? dir = null, rulesPath = null, outPath = null;

        for (var i = 0; i < args.Length; i++)
        {
            var a = args[i];
            switch (a)
            {
                case "--plan":
                    break;
                case "--dir":
                    if (!TryTake(args, ref i, out dir))
                    {
                        return Fail(ExitCodes.Usage, "--dir requires a value");
                    }

                    break;
                case "--rules":
                    if (!TryTake(args, ref i, out rulesPath))
                    {
                        return Fail(ExitCodes.Usage, "--rules requires a value");
                    }

                    break;
                case "--out":
                    if (!TryTake(args, ref i, out outPath))
                    {
                        return Fail(ExitCodes.Usage, "--out requires a value");
                    }

                    break;
                default:
                    return Fail(ExitCodes.Usage, $"unknown argument '{a}'");
            }
        }

        if (dir is null || rulesPath is null || outPath is null)
        {
            return Fail(ExitCodes.Usage, "--dir, --rules and --out are all required");
        }

        RuleSet rules;
        try
        {
            rules = RuleSetIo.Load(rulesPath);
        }
        catch (RuleConfigException ex)
        {
            return Fail(ExitCodes.BadRules, ex.Message);
        }

        RenamePlan plan;
        try
        {
            plan = PlanBuilder.Build(dir, rules);
        }
        catch (RuleConfigException ex)
        {
            return Fail(ExitCodes.BadRules, ex.Message);
        }
        catch (Exception ex)
        {
            return Fail(ExitCodes.IoError, $"cannot read '{dir}': {ex.Message}");
        }

        try
        {
            PlanWriter.WriteFile(outPath, plan);
        }
        catch (Exception ex)
        {
            return Fail(ExitCodes.IoError, $"cannot write '{outPath}': {ex.Message}");
        }

        var s = plan.Summary;
        Console.Out.WriteLine(string.Format(
            CultureInfo.InvariantCulture,
            "planned {0} file(s): ok={1} collision={2} unchanged={3} invalid={4} -> {5}",
            s.Total,
            s.Ok,
            s.Collision,
            s.Unchanged,
            s.Invalid,
            Path.GetFullPath(outPath)));
        Console.Out.Flush();
        return ExitCodes.Success;
    }

    private static bool TryTake(string[] args, ref int i, out string? value)
    {
        if (i + 1 >= args.Length)
        {
            value = null;
            return false;
        }

        i++;
        value = args[i];
        return true;
    }

    private static int Fail(int code, string message)
    {
        Console.Error.WriteLine("error: " + message);
        if (code == ExitCodes.Usage)
        {
            Console.Error.WriteLine(Usage);
        }

        Console.Error.Flush();
        return code;
    }
}

