using BatchRenameStudio.Cli;
using BatchRenameStudio.Ui;

namespace BatchRenameStudio;

internal static class Program
{
    [STAThread]
    private static int Main(string[] args)
    {
        if (args.Length > 0)
        {
            ConsoleBridge.Attach();

            if (args.Contains("--plan"))
            {
                return HeadlessRunner.Run(args);
            }

            if (args.Contains("--help") || args.Contains("-h") || args.Contains("/?"))
            {
                Console.Out.WriteLine(HeadlessRunner.Usage);
                Console.Out.WriteLine("run without arguments to open the GUI");
                return ExitCodes.Success;
            }

            Console.Error.WriteLine("error: unrecognised arguments");
            Console.Error.WriteLine(HeadlessRunner.Usage);
            return ExitCodes.Usage;
        }

        ApplicationConfiguration.Initialize();
        Application.Run(new MainForm());
        return ExitCodes.Success;
    }
}

