using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>
/// The whole GUI: folder on top, rule chain on the left, live preview on the right, actions at the bottom.
/// Preview and apply both go through <see cref="PlanBuilder"/>, so what the grid shows is exactly what the
/// headless planner would emit.
/// </summary>
public sealed class MainForm : Form
{
    private readonly TextBox _folderBox = new() { ReadOnly = true, Dock = DockStyle.Fill };
    private readonly ComboBox _applyToBox = new() { DropDownStyle = ComboBoxStyle.DropDownList, Width = 170 };
    private readonly ComboBox _sortBox = new() { DropDownStyle = ComboBoxStyle.DropDownList, Width = 130 };
    private readonly ListBox _stepList = new() { Dock = DockStyle.Fill, IntegralHeight = false };
    private readonly DataGridView _grid = new();
    private readonly ToolStripStatusLabel _summaryLabel = new() { Spring = true, TextAlign = ContentAlignment.MiddleLeft };
    private readonly Button _applyButton = new() { Text = "Apply rename", Width = 130, Height = 30 };
    private readonly Button _undoButton = new() { Text = "Undo last", Width = 110, Height = 30, Enabled = false };
    private readonly Button _exportButton = new() { Text = "Export plan.json…", Width = 150, Height = 30 };

    private readonly RuleSet _rules = new();
    private readonly Stack<RenameBatch> _undoStack = new();

    private string _folder = string.Empty;
    private RenamePlan? _plan;
    private bool _suppressPreview;

    public MainForm()
    {
        Text = "Batch Rename Studio";
        MinimumSize = new Size(1020, 620);
        Size = new Size(1180, 720);
        StartPosition = FormStartPosition.CenterScreen;

        BuildLayout();
        BindEvents();
        RefreshStepList();
        UpdatePreview();
    }

    // ---------------------------------------------------------------- layout

    private void BuildLayout()
    {
        var root = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 1,
            RowCount = 3,
            Padding = new Padding(10),
        };
        root.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        root.RowStyles.Add(new RowStyle(SizeType.Percent, 100));
        root.RowStyles.Add(new RowStyle(SizeType.AutoSize));

        root.Controls.Add(BuildSourceBar(), 0, 0);
        root.Controls.Add(BuildSplit(), 0, 1);
        root.Controls.Add(BuildActionBar(), 0, 2);

        var status = new StatusStrip();
        status.Items.Add(_summaryLabel);

        Controls.Add(root);
        Controls.Add(status);
    }

    private Control BuildSourceBar()
    {
        var bar = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 7,
            RowCount = 1,
            AutoSize = true,
            Margin = new Padding(0, 0, 0, 8),
        };
        bar.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        bar.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 100));
        for (var i = 0; i < 5; i++)
        {
            bar.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        }

        var browse = new Button { Text = "Choose folder…", AutoSize = true };
        browse.Click += (_, _) => ChooseFolder();

        var reload = new Button { Text = "Reload", AutoSize = true };
        reload.Click += (_, _) => UpdatePreview();

        _applyToBox.Items.AddRange(new object[] { "Name only", "Name + extension" });
        _applyToBox.SelectedIndex = 0;

        _sortBox.Items.AddRange(new object[] { "Sort: name", "Sort: created", "Sort: modified" });
        _sortBox.SelectedIndex = 0;

        bar.Controls.Add(new Label { Text = "Folder:", AutoSize = true, Anchor = AnchorStyles.Left, Margin = new Padding(0, 8, 6, 0) }, 0, 0);
        bar.Controls.Add(_folderBox, 1, 0);
        bar.Controls.Add(browse, 2, 0);
        bar.Controls.Add(reload, 3, 0);
        bar.Controls.Add(new Label { Text = "Apply to:", AutoSize = true, Anchor = AnchorStyles.Left, Margin = new Padding(16, 8, 6, 0) }, 4, 0);
        bar.Controls.Add(_applyToBox, 5, 0);
        bar.Controls.Add(_sortBox, 6, 0);
        return bar;
    }

    private Control BuildSplit()
    {
        var split = new SplitContainer
        {
            Dock = DockStyle.Fill,
            SplitterDistance = 380,
            FixedPanel = FixedPanel.Panel1,
        };

        split.Panel1.Controls.Add(BuildRulePanel());
        split.Panel2.Controls.Add(BuildPreviewPanel());
        return split;
    }

    private Control BuildRulePanel()
    {
        var panel = new TableLayoutPanel
        {
            Dock = DockStyle.Fill,
            ColumnCount = 1,
            RowCount = 3,
            Margin = new Padding(0, 0, 6, 0),
        };
        panel.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        panel.RowStyles.Add(new RowStyle(SizeType.Percent, 100));
        panel.RowStyles.Add(new RowStyle(SizeType.AutoSize));

        panel.Controls.Add(new Label { Text = "Rule steps (applied top to bottom)", AutoSize = true, Margin = new Padding(0, 0, 0, 4) }, 0, 0);
        panel.Controls.Add(_stepList, 0, 1);

        var buttons = new FlowLayoutPanel { Dock = DockStyle.Fill, AutoSize = true, Margin = new Padding(0, 6, 0, 0) };

        var add = new Button { Text = "Add step ▾", AutoSize = true };
        var addMenu = new ContextMenuStrip();
        addMenu.Items.Add("Replace…", null, (_, _) => AddStep(new ReplaceStep()));
        addMenu.Items.Add("Insert…", null, (_, _) => AddStep(new InsertStep()));
        addMenu.Items.Add("Remove…", null, (_, _) => AddStep(new RemoveStep { Count = 1 }));
        addMenu.Items.Add("Sequence…", null, (_, _) => AddStep(new SequenceStep()));
        addMenu.Items.Add("Case…", null, (_, _) => AddStep(new CaseStep()));
        addMenu.Items.Add("Extension…", null, (_, _) => AddStep(new ExtensionStep()));
        add.Click += (_, _) => addMenu.Show(add, new Point(0, add.Height));

        var edit = new Button { Text = "Edit…", AutoSize = true };
        edit.Click += (_, _) => EditSelectedStep();

        var remove = new Button { Text = "Delete", AutoSize = true };
        remove.Click += (_, _) => RemoveSelectedStep();

        var up = new Button { Text = "↑", Width = 34 };
        up.Click += (_, _) => MoveSelectedStep(-1);

        var down = new Button { Text = "↓", Width = 34 };
        down.Click += (_, _) => MoveSelectedStep(1);

        var load = new Button { Text = "Load rules…", AutoSize = true };
        load.Click += (_, _) => LoadRules();

        var save = new Button { Text = "Save rules…", AutoSize = true };
        save.Click += (_, _) => SaveRules();

        buttons.Controls.AddRange(new Control[] { add, edit, remove, up, down, load, save });
        panel.Controls.Add(buttons, 0, 2);
        return panel;
    }

    private Control BuildPreviewPanel()
    {
        _grid.Dock = DockStyle.Fill;
        _grid.AllowUserToAddRows = false;
        _grid.AllowUserToDeleteRows = false;
        _grid.ReadOnly = true;
        _grid.RowHeadersVisible = false;
        _grid.SelectionMode = DataGridViewSelectionMode.FullRowSelect;
        _grid.AutoSizeColumnsMode = DataGridViewAutoSizeColumnsMode.Fill;
        _grid.MultiSelect = true;

        _grid.Columns.Add(NewColumn("num", "#", 40, DataGridViewAutoSizeColumnMode.None));
        _grid.Columns.Add(NewColumn("original", "Original", 100, DataGridViewAutoSizeColumnMode.Fill));
        _grid.Columns.Add(NewColumn("proposed", "Proposed", 100, DataGridViewAutoSizeColumnMode.Fill));
        _grid.Columns.Add(NewColumn("status", "Status", 90, DataGridViewAutoSizeColumnMode.None));
        _grid.Columns.Add(NewColumn("reason", "Reason", 160, DataGridViewAutoSizeColumnMode.None));

        var panel = new TableLayoutPanel { Dock = DockStyle.Fill, ColumnCount = 1, RowCount = 2, Margin = new Padding(6, 0, 0, 0) };
        panel.RowStyles.Add(new RowStyle(SizeType.AutoSize));
        panel.RowStyles.Add(new RowStyle(SizeType.Percent, 100));
        panel.Controls.Add(new Label { Text = "Preview", AutoSize = true, Margin = new Padding(0, 0, 0, 4) }, 0, 0);
        panel.Controls.Add(_grid, 0, 1);
        return panel;
    }

    private static DataGridViewTextBoxColumn NewColumn(
        string name,
        string header,
        int width,
        DataGridViewAutoSizeColumnMode mode) => new()
    {
        Name = name,
        HeaderText = header,
        Width = width,
        AutoSizeMode = mode,
        SortMode = DataGridViewColumnSortMode.NotSortable,
    };

    private Control BuildActionBar()
    {
        var bar = new FlowLayoutPanel
        {
            Dock = DockStyle.Fill,
            FlowDirection = FlowDirection.RightToLeft,
            AutoSize = true,
            Margin = new Padding(0, 8, 0, 0),
        };
        bar.Controls.Add(_applyButton);
        bar.Controls.Add(_undoButton);
        bar.Controls.Add(_exportButton);
        return bar;
    }

    private void BindEvents()
    {
        _applyToBox.SelectedIndexChanged += (_, _) =>
        {
            _rules.ApplyTo = _applyToBox.SelectedIndex == 1 ? ApplyTo.NameAndExtension : ApplyTo.Name;
            UpdatePreview();
        };

        _sortBox.SelectedIndexChanged += (_, _) =>
        {
            _rules.Sort = _sortBox.SelectedIndex switch
            {
                1 => SortMode.Created,
                2 => SortMode.Modified,
                _ => SortMode.Name,
            };
            UpdatePreview();
        };

        _stepList.DoubleClick += (_, _) => EditSelectedStep();
        _applyButton.Click += (_, _) => ApplyRename();
        _undoButton.Click += (_, _) => UndoLast();
        _exportButton.Click += (_, _) => ExportPlan();
    }

    // ---------------------------------------------------------------- rules

    private void AddStep(RuleStep step)
    {
        if (StepEditorForm.Edit(this, step))
        {
            _rules.Steps.Add(step);
            RefreshStepList();
            _stepList.SelectedIndex = _rules.Steps.Count - 1;
            UpdatePreview();
        }
    }

    private void EditSelectedStep()
    {
        var i = _stepList.SelectedIndex;
        if (i < 0 || i >= _rules.Steps.Count)
        {
            return;
        }

        var working = _rules.Steps[i].Clone();
        if (StepEditorForm.Edit(this, working))
        {
            _rules.Steps[i] = working;
            RefreshStepList();
            _stepList.SelectedIndex = i;
            UpdatePreview();
        }
    }

    private void RemoveSelectedStep()
    {
        var i = _stepList.SelectedIndex;
        if (i < 0 || i >= _rules.Steps.Count)
        {
            return;
        }

        _rules.Steps.RemoveAt(i);
        RefreshStepList();
        _stepList.SelectedIndex = Math.Min(i, _rules.Steps.Count - 1);
        UpdatePreview();
    }

    private void MoveSelectedStep(int delta)
    {
        var i = _stepList.SelectedIndex;
        var target = i + delta;
        if (i < 0 || target < 0 || target >= _rules.Steps.Count)
        {
            return;
        }

        (_rules.Steps[i], _rules.Steps[target]) = (_rules.Steps[target], _rules.Steps[i]);
        RefreshStepList();
        _stepList.SelectedIndex = target;
        UpdatePreview();
    }

    private void RefreshStepList()
    {
        var selected = _stepList.SelectedIndex;
        _stepList.BeginUpdate();
        _stepList.Items.Clear();
        for (var i = 0; i < _rules.Steps.Count; i++)
        {
            _stepList.Items.Add($"{i + 1}. {_rules.Steps[i].Describe()}");
        }

        _stepList.EndUpdate();
        if (selected >= 0 && selected < _stepList.Items.Count)
        {
            _stepList.SelectedIndex = selected;
        }
    }

    private void LoadRules()
    {
        using var dlg = new OpenFileDialog { Filter = "Rule sets (*.json)|*.json|All files (*.*)|*.*" };
        if (dlg.ShowDialog(this) != DialogResult.OK)
        {
            return;
        }

        try
        {
            var loaded = RuleSetIo.Load(dlg.FileName);
            _suppressPreview = true;
            _rules.Steps.Clear();
            _rules.Steps.AddRange(loaded.Steps);
            _rules.ApplyTo = loaded.ApplyTo;
            _rules.Sort = loaded.Sort;
            _applyToBox.SelectedIndex = loaded.ApplyTo == ApplyTo.NameAndExtension ? 1 : 0;
            _sortBox.SelectedIndex = loaded.Sort switch
            {
                SortMode.Created => 1,
                SortMode.Modified => 2,
                _ => 0,
            };
            _suppressPreview = false;
            RefreshStepList();
            UpdatePreview();
        }
        catch (RuleConfigException ex)
        {
            _suppressPreview = false;
            Warn(ex.Message);
        }
    }

    private void SaveRules()
    {
        using var dlg = new SaveFileDialog
        {
            Filter = "Rule sets (*.json)|*.json",
            FileName = "rules.json",
        };
        if (dlg.ShowDialog(this) != DialogResult.OK)
        {
            return;
        }

        try
        {
            RuleSetIo.Save(dlg.FileName, _rules);
        }
        catch (Exception ex)
        {
            Warn(ex.Message);
        }
    }

    // ---------------------------------------------------------------- preview

    private void ChooseFolder()
    {
        using var dlg = new FolderBrowserDialog { ShowNewFolderButton = false };
        if (!string.IsNullOrEmpty(_folder))
        {
            dlg.SelectedPath = _folder;
        }

        if (dlg.ShowDialog(this) != DialogResult.OK)
        {
            return;
        }

        _folder = dlg.SelectedPath;
        _folderBox.Text = _folder;
        _undoStack.Clear();
        _undoButton.Enabled = false;
        UpdatePreview();
    }

    private void UpdatePreview()
    {
        if (_suppressPreview)
        {
            return;
        }

        _grid.Rows.Clear();
        _plan = null;

        if (string.IsNullOrEmpty(_folder))
        {
            _summaryLabel.Text = "Choose a folder to begin.";
            _applyButton.Enabled = false;
            _exportButton.Enabled = false;
            return;
        }

        try
        {
            _plan = PlanBuilder.Build(_folder, _rules);
        }
        catch (RuleConfigException ex)
        {
            _summaryLabel.Text = "Rule error: " + ex.Message;
            _applyButton.Enabled = false;
            _exportButton.Enabled = false;
            return;
        }
        catch (Exception ex)
        {
            _summaryLabel.Text = "Cannot read folder: " + ex.Message;
            _applyButton.Enabled = false;
            _exportButton.Enabled = false;
            return;
        }

        foreach (var item in _plan.Items)
        {
            var row = _grid.Rows[_grid.Rows.Add(
                item.Ordinal + 1,
                item.Original,
                item.Proposed,
                item.Status.Wire(),
                item.Reason)];

            row.DefaultCellStyle.BackColor = item.Status switch
            {
                PlanStatus.Ok => Color.FromArgb(232, 248, 235),
                PlanStatus.Collision => Color.FromArgb(253, 231, 231),
                PlanStatus.Invalid => Color.FromArgb(253, 243, 219),
                _ => Color.White,
            };
        }

        var s = _plan.Summary;
        _summaryLabel.Text =
            $"{s.Total} file(s) — ok {s.Ok}, collision {s.Collision}, unchanged {s.Unchanged}, invalid {s.Invalid}";
        _applyButton.Enabled = s.Ok > 0;
        _exportButton.Enabled = true;
    }

    // ---------------------------------------------------------------- actions

    private void ApplyRename()
    {
        if (_plan is null)
        {
            return;
        }

        var ok = _plan.Summary.Ok;
        if (ok == 0)
        {
            return;
        }

        var skipped = _plan.Summary.Total - ok;
        var message = $"Rename {ok} file(s)?" +
                      (skipped > 0 ? $"\n\n{skipped} file(s) will be skipped (unchanged, collision or invalid)." : string.Empty);
        if (MessageBox.Show(this, message, "Confirm rename", MessageBoxButtons.OKCancel, MessageBoxIcon.Question)
            != DialogResult.OK)
        {
            return;
        }

        var outcome = RenameExecutor.Execute(_plan);
        if (outcome.Applied.Count > 0)
        {
            _undoStack.Push(new RenameBatch
            {
                Directory = _plan.Directory,
                Ops = outcome.Applied.ToList(),
                PerformedAt = DateTime.Now,
            });
            _undoButton.Enabled = true;
        }

        if (!outcome.Success)
        {
            Warn("Some files could not be renamed:\n\n" + string.Join("\n", outcome.Errors.Take(12)));
        }

        UpdatePreview();
    }

    private void UndoLast()
    {
        if (_undoStack.Count == 0)
        {
            return;
        }

        var batch = _undoStack.Peek();
        if (MessageBox.Show(this, $"Undo {batch.Describe()}?", "Confirm undo", MessageBoxButtons.OKCancel,
                MessageBoxIcon.Question) != DialogResult.OK)
        {
            return;
        }

        var outcome = RenameExecutor.Undo(batch);
        if (outcome.Success)
        {
            _undoStack.Pop();
        }
        else
        {
            Warn("Undo did not fully succeed:\n\n" + string.Join("\n", outcome.Errors.Take(12)));
        }

        _undoButton.Enabled = _undoStack.Count > 0;
        UpdatePreview();
    }

    private void ExportPlan()
    {
        if (_plan is null)
        {
            return;
        }

        using var dlg = new SaveFileDialog { Filter = "Plan (*.json)|*.json", FileName = "plan.json" };
        if (dlg.ShowDialog(this) != DialogResult.OK)
        {
            return;
        }

        try
        {
            PlanWriter.WriteFile(dlg.FileName, _plan);
        }
        catch (Exception ex)
        {
            Warn(ex.Message);
        }
    }

    private void Warn(string message)
        => MessageBox.Show(this, message, "Batch Rename Studio", MessageBoxButtons.OK, MessageBoxIcon.Warning);
}

