using System.Text.RegularExpressions;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Ui;

/// <summary>Modal editor for one rule step. Fields are built from the concrete step type.</summary>
public sealed class StepEditorForm : Form
{
    private readonly RuleStep _step;
    private readonly TableLayoutPanel _fields;
    private readonly List<Func<string?>> _validators = new();
    private readonly List<Action> _committers = new();

    private StepEditorForm(RuleStep step)
    {
        _step = step;
        Text = "Step — " + step.Op;
        FormBorderStyle = FormBorderStyle.FixedDialog;
        MinimizeBox = false;
        MaximizeBox = false;
        StartPosition = FormStartPosition.CenterParent;
        ClientSize = new Size(430, 10);
        AutoSize = true;
        AutoSizeMode = AutoSizeMode.GrowAndShrink;

        _fields = new TableLayoutPanel
        {
            ColumnCount = 2,
            AutoSize = true,
            AutoSizeMode = AutoSizeMode.GrowAndShrink,
            Dock = DockStyle.Top,
            Padding = new Padding(12),
        };
        _fields.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
        _fields.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute, 270));

        BuildFields();

        var ok = new Button { Text = "OK", DialogResult = DialogResult.None, AutoSize = true };
        var cancel = new Button { Text = "Cancel", DialogResult = DialogResult.Cancel, AutoSize = true };
        ok.Click += (_, _) => Commit();

        var buttons = new FlowLayoutPanel
        {
            FlowDirection = FlowDirection.RightToLeft,
            Dock = DockStyle.Top,
            AutoSize = true,
            Padding = new Padding(12, 0, 12, 12),
        };
        buttons.Controls.Add(ok);
        buttons.Controls.Add(cancel);

        Controls.Add(buttons);
        Controls.Add(_fields);
        AcceptButton = ok;
        CancelButton = cancel;
    }

    /// <summary>Shows the dialog; on OK the step instance is updated in place.</summary>
    public static bool Edit(IWin32Window owner, RuleStep step)
    {
        using var form = new StepEditorForm(step);
        return form.ShowDialog(owner) == DialogResult.OK;
    }

    private void Commit()
    {
        foreach (var validate in _validators)
        {
            var error = validate();
            if (error is not null)
            {
                MessageBox.Show(this, error, "Invalid value", MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return;
            }
        }

        foreach (var commit in _committers)
        {
            commit();
        }

        DialogResult = DialogResult.OK;
        Close();
    }

    private void BuildFields()
    {
        switch (_step)
        {
            case ReplaceStep r:
            {
                var find = Text_(r.Find);
                var with = Text_(r.ReplaceWith);
                var regex = Check("Regular expression ($1 back-references allowed)", r.Regex);
                var ignore = Check("Ignore case", r.IgnoreCase);
                Row("Find:", find);
                Row("Replace with:", with);
                Row(string.Empty, regex);
                Row(string.Empty, ignore);
                _validators.Add(() =>
                {
                    if (!regex.Checked)
                    {
                        return null;
                    }

                    try
                    {
                        _ = new Regex(find.Text);
                        return null;
                    }
                    catch (ArgumentException ex)
                    {
                        return "Invalid regular expression: " + ex.Message;
                    }
                });
                _committers.Add(() =>
                {
                    r.Find = find.Text;
                    r.ReplaceWith = with.Text;
                    r.Regex = regex.Checked;
                    r.IgnoreCase = ignore.Checked;
                });
                break;
            }

            case InsertStep i:
            {
                var text = Text_(i.Text);
                var position = Combo(new[] { "prefix", "suffix", "index" }, (int)i.Position);
                var index = Number(i.Index, 0, 10000);
                Row("Text:", text);
                Row("Position:", position);
                Row("Index:", index);
                position.SelectedIndexChanged += (_, _) => index.Enabled = position.SelectedIndex == 2;
                index.Enabled = i.Position == InsertPosition.Index;
                _committers.Add(() =>
                {
                    i.Text = text.Text;
                    i.Position = (InsertPosition)position.SelectedIndex;
                    i.Index = (int)index.Value;
                });
                break;
            }

            case RemoveStep rm:
            {
                var from = Number(rm.From, 0, 10000);
                var count = Number(rm.Count, 0, 10000);
                Row("From index:", from);
                Row("Count:", count);
                _committers.Add(() =>
                {
                    rm.From = (int)from.Value;
                    rm.Count = (int)count.Value;
                });
                break;
            }

            case SequenceStep q:
            {
                var pattern = Text_(q.Pattern);
                var start = Number(q.Start, -100000, 100000);
                var step = Number(q.Step, -100000, 100000);
                var position = Combo(new[] { "prefix", "suffix" }, (int)q.Position);
                Row("Pattern:", pattern);
                Row(string.Empty, Hint("Use one {n:000} token; the zeros set the pad width."));
                Row("Start:", start);
                Row("Step:", step);
                Row("Position:", position);
                _committers.Add(() =>
                {
                    q.Pattern = pattern.Text;
                    q.Start = (int)start.Value;
                    q.Step = (int)step.Value;
                    q.Position = (AffixPosition)position.SelectedIndex;
                });
                break;
            }

            case CaseStep c:
            {
                var mode = Combo(new[] { "upper", "lower", "title" }, (int)c.Mode);
                Row("Mode:", mode);
                _committers.Add(() => c.Mode = (CaseMode)mode.SelectedIndex);
                break;
            }

            case ExtensionStep e:
            {
                var mode = Combo(new[] { "lower", "upper", "set" }, (int)e.Mode);
                var value = Text_(e.Value);
                Row("Mode:", mode);
                Row("Value:", value);
                value.Enabled = e.Mode == ExtensionMode.Set;
                mode.SelectedIndexChanged += (_, _) => value.Enabled = mode.SelectedIndex == 2;
                _committers.Add(() =>
                {
                    e.Mode = (ExtensionMode)mode.SelectedIndex;
                    e.Value = value.Text;
                });
                break;
            }
        }
    }

    private void Row(string label, Control control)
    {
        var row = _fields.RowCount;
        _fields.RowCount = row + 1;
        _fields.Controls.Add(
            new Label { Text = label, AutoSize = true, Anchor = AnchorStyles.Left, Margin = new Padding(0, 6, 8, 4) },
            0,
            row);
        _fields.Controls.Add(control, 1, row);
    }

    private static TextBox Text_(string value) => new() { Text = value, Width = 260 };

    private static CheckBox Check(string text, bool value) => new() { Text = text, Checked = value, AutoSize = true };

    private static NumericUpDown Number(int value, int min, int max) => new()
    {
        Minimum = min,
        Maximum = max,
        Value = Math.Clamp(value, min, max),
        Width = 100,
    };

    private static ComboBox Combo(string[] items, int selected)
    {
        var box = new ComboBox { DropDownStyle = ComboBoxStyle.DropDownList, Width = 140 };
        box.Items.AddRange(items);
        box.SelectedIndex = Math.Clamp(selected, 0, items.Length - 1);
        return box;
    }

    private static Label Hint(string text) => new()
    {
        Text = text,
        AutoSize = true,
        ForeColor = SystemColors.GrayText,
        MaximumSize = new Size(260, 0),
    };
}

