using System.Runtime.InteropServices;
using System.Text;

namespace BatchRenameStudio.Cli;

/// <summary>
/// The app is built as a console-subsystem executable so that a shell waits for it and sees its exit
/// code in <c>--plan</c> mode. When it is launched for the GUI and owns its console window, that window
/// is hidden; a console inherited from a terminal is left alone.
/// </summary>
public static class ConsoleBridge
{
    private const int SwHide = 0;

    [DllImport("kernel32.dll")]
    private static extern IntPtr GetConsoleWindow();

    [DllImport("kernel32.dll", SetLastError = true)]
    private static extern uint GetConsoleProcessList(uint[] processList, uint count);

    [DllImport("user32.dll")]
    [return: MarshalAs(UnmanagedType.Bool)]
    private static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);

    /// <summary>Hides the console window, but only when this process is its sole owner.</summary>
    public static void HideOwnConsole()
    {
        var window = GetConsoleWindow();
        if (window == IntPtr.Zero)
        {
            return;
        }

        var buffer = new uint[4];
        var count = GetConsoleProcessList(buffer, (uint)buffer.Length);
        if (count == 1)
        {
            ShowWindow(window, SwHide);
        }
    }

    /// <summary>Makes stdout/stderr emit UTF-8 so non-ASCII paths survive the summary line.</summary>
    public static void UseUtf8()
    {
        try
        {
            Console.OutputEncoding = new UTF8Encoding(false);
        }
        catch (IOException)
        {
            // No console attached (e.g. fully redirected in an odd host) — the default writer is fine.
        }
    }
}

