var root = Path.Combine(Path.GetTempPath(), "brs-exec-test");
if (Directory.Exists(root))
{
    Directory.Delete(root, true);
}

Directory.CreateDirectory(root);
File.WriteAllText(Path.Combine(root, "a.txt"), "A");
File.WriteAllText(Path.Combine(root, "b.txt"), "B");
File.WriteAllText(Path.Combine(root, "keep.md"), "K");

// Swap a.txt <-> b.txt: every proposed name collides with an existing file, so build the ops directly.
var ops = new List<RenameOp>
{
    new(root, "a.txt", "b.txt"),
    new(root, "b.txt", "a.txt"),
};

var outcome = RenameExecutor.Execute(root, ops);
Console.WriteLine($"swap success={outcome.Success} errors={string.Join(";", outcome.Errors)}");
Console.WriteLine("a.txt now holds: " + File.ReadAllText(Path.Combine(root, "a.txt")));
Console.WriteLine("b.txt now holds: " + File.ReadAllText(Path.Combine(root, "b.txt")));

var batch = new RenameBatch { Directory = root, Ops = outcome.Applied.ToList(), PerformedAt = DateTime.Now };
var undo = RenameExecutor.Undo(batch);
Console.WriteLine($"undo success={undo.Success} errors={string.Join(";", undo.Errors)}");
Console.WriteLine("a.txt restored: " + File.ReadAllText(Path.Combine(root, "a.txt")));
Console.WriteLine("b.txt restored: " + File.ReadAllText(Path.Combine(root, "b.txt")));

// Plan-driven apply: prefix every name, then undo it.
var rules = RuleSetIo.Parse("""
{"applyTo":"name","sort":"name","steps":[{"op":"sequence","pattern":"{n:00}_","start":1,"step":1,"position":"prefix"}]}
""");
var plan = PlanBuilder.Build(root, rules);
var applied = RenameExecutor.Execute(plan);
Console.WriteLine($"apply success={applied.Success} count={applied.Applied.Count}");
Console.WriteLine("after apply: " + string.Join(", ", Directory.GetFiles(root).Select(Path.GetFileName).Order()));
var batch2 = new RenameBatch { Directory = root, Ops = applied.Applied.ToList(), PerformedAt = DateTime.Now };
RenameExecutor.Undo(batch2);
Console.WriteLine("after undo: " + string.Join(", ", Directory.GetFiles(root).Select(Path.GetFileName).Order()));
Console.WriteLine("leftover temp files: " +
                  Directory.GetFiles(root).Count(p => Path.GetFileName(p).StartsWith(".brs-tmp-", StringComparison.Ordinal)));

// A few pure-engine spot checks against the contract text.
void Check(string label, string actual, string expected)
    => Console.WriteLine($"{(actual == expected ? "PASS" : "FAIL")} {label}: '{actual}' (expected '{expected}')");

var titleRules = RuleSetIo.Parse("""{"applyTo":"name","sort":"name","steps":[{"op":"case","mode":"title"}]}""");
Check("title", RuleEngine.Apply("hello-wORLD 3rd.TXT", titleRules, 0), "Hello-World 3rd.TXT");

var removeRules = RuleSetIo.Parse("""{"applyTo":"name","sort":"name","steps":[{"op":"remove","from":90,"count":90}]}""");
Check("remove clamp", RuleEngine.Apply("abc.txt", removeRules, 0), "abc.txt");

var groupRules = RuleSetIo.Parse("""
{"applyTo":"name","sort":"name","steps":[{"op":"replace","find":"(\\d+)-(\\w+)","replaceWith":"$2_$1","regex":true}]}
""");
Check("regex groups", RuleEngine.Apply("12-abc.txt", groupRules, 0), "abc_12.txt");

var extRules = RuleSetIo.Parse("""{"applyTo":"name","sort":"name","steps":[{"op":"extension","mode":"set","value":"bak"}]}""");
Check("ext on dotfile", RuleEngine.Apply(".gitignore", extRules, 0), ".gitignore.bak");

Check("invalid: reserved", PlanBuilder.InvalidReason("com4.log") is null ? "valid" : "invalid", "invalid");
Check("invalid: long", PlanBuilder.InvalidReason(new string('x', 256)) is null ? "valid" : "invalid", "invalid");
Check("valid: 255", PlanBuilder.InvalidReason(new string('x', 255)) is null ? "valid" : "invalid", "valid");

Directory.Delete(root, true);

