using System.Text;
using BatchRenameStudio.Core;

namespace BatchRenameStudio.Tests;

/// <summary>
/// Dependency-free smoke tests for the planning core and the rename executor.
/// Run with: dotnet run --project tests/CoreSmokeTests -c Release
/// Exit code 0 = all checks passed, 1 = at least one failed.
/// </summary>
internal static class Program
{
    private static int _failures;

    private static int Main()
    {
        EngineChecks();
        StatusChecks();
        SortAndSequenceChecks();
        PlanFileChecks();
        ExecutorChecks();

        Console.WriteLine(_failures == 0 ? "ALL CHECKS PASSED" : $"{_failures} CHECK(S) FAILED");
        return _failures == 0 ? 0 : 1;
    }

    // ------------------------------------------------------------ helpers

    private static void Check(string label, object? actual, object? expected)
    {
        var ok = Equals(actual?.ToString(), expected?.ToString());
        if (!ok)
        {
            _failures++;
        }

        Console.WriteLine($"{(ok ? "PASS" : "FAIL")}  {label}: '{actual}'" + (ok ? string.Empty : $" (expected '{expected}')"));
    }

    private static RuleSet Rules(string json) => RuleSetIo.Parse(json);

    private static string Apply(string name, string json, int ordinal = 0)
        => RuleEngine.Apply(name, Rules(json), ordinal);

    private static string NewTempDir()
    {
        var dir = Path.Combine(Path.GetTempPath(), "brs-tests-" + Guid.NewGuid().ToString("N")[..8]);
        Directory.CreateDirectory(dir);
        return dir;
    }

    // ------------------------------------------------------------ checks

    private static void EngineChecks()
    {
        Console.WriteLine("-- engine --");

        Check("split: dotfile keeps whole name as base", NameParts.Split(".gitignore").Base, ".gitignore");
        Check("split: dotfile has empty ext", NameParts.Split(".gitignore").Ext, string.Empty);
        Check("split: last dot wins", NameParts.Split("a.tar.gz").Base, "a.tar");

        Check(
            "replace: all occurrences, literal",
            Apply("a-a-a.txt", """{"steps":[{"op":"replace","find":"a","replaceWith":"b"}]}"""),
            "b-b-b.txt");
        Check(
            "replace: ignoreCase literal",
            Apply("Foo_FOO.txt", """{"steps":[{"op":"replace","find":"foo","replaceWith":"x","ignoreCase":true}]}"""),
            "x_x.txt");
        Check(
            "replace: regex groups",
            Apply("12-abc.txt", """{"steps":[{"op":"replace","find":"(\\d+)-(\\w+)","replaceWith":"$2_$1","regex":true}]}"""),
            "abc_12.txt");

        Check(
            "insert: prefix",
            Apply("a.txt", """{"steps":[{"op":"insert","text":"pre-","position":"prefix"}]}"""),
            "pre-a.txt");
        Check(
            "insert: suffix targets base only",
            Apply("a.txt", """{"steps":[{"op":"insert","text":"-end","position":"suffix"}]}"""),
            "a-end.txt");
        Check(
            "insert: index clamped to length",
            Apply("abc.txt", """{"steps":[{"op":"insert","text":"X","position":"index","index":99}]}"""),
            "abcX.txt");

        Check(
            "remove: from/count",
            Apply("abcdef.txt", """{"steps":[{"op":"remove","from":1,"count":3}]}"""),
            "aef.txt");
        Check(
            "remove: clamped past end",
            Apply("abc.txt", """{"steps":[{"op":"remove","from":90,"count":90}]}"""),
            "abc.txt");

        Check(
            "case: title runs of letters",
            Apply("hello-wORLD 3rd", """{"steps":[{"op":"case","mode":"title"}]}"""),
            "Hello-World 3Rd");
        Check(
            "case: upper on name only",
            Apply("mixed.TxT", """{"steps":[{"op":"case","mode":"upper"}]}"""),
            "MIXED.TxT");
        Check(
            "case: nameAndExtension covers the dot part",
            Apply("mixed.TxT", """{"applyTo":"nameAndExtension","steps":[{"op":"case","mode":"lower"}]}"""),
            "mixed.txt");

        Check(
            "extension: lower ignores applyTo",
            Apply("a.TXT", """{"applyTo":"name","steps":[{"op":"extension","mode":"lower"}]}"""),
            "a.txt");
        Check(
            "extension: set on a file without one",
            Apply("plain", """{"steps":[{"op":"extension","mode":"set","value":"md"}]}"""),
            "plain.md");
        Check(
            "extension: dotfile gains an extension",
            Apply(".gitignore", """{"steps":[{"op":"extension","mode":"set","value":"bak"}]}"""),
            ".gitignore.bak");
        Check(
            "extension: nameAndExtension re-splits the target",
            Apply("a.tar.gz", """{"applyTo":"nameAndExtension","steps":[{"op":"extension","mode":"upper"}]}"""),
            "a.tar.GZ");

        Check(
            "sequence: pad width and position",
            Apply("a.txt", """{"steps":[{"op":"sequence","pattern":"{n:0000}_","start":7,"step":1,"position":"prefix"}]}""", 0),
            "0007_a.txt");
        Check(
            "sequence: suffix with step",
            Apply("a.txt", """{"steps":[{"op":"sequence","pattern":"-{n:00}","start":1,"step":5,"position":"suffix"}]}""", 2),
            "a-11.txt");
        Check("sequence: renderer", RuleEngine.RenderSequence("img{n:000}v", 42), "img042v");

        Check(
            "steps apply in order",
            Apply("abc.txt", """{"steps":[{"op":"case","mode":"upper"},{"op":"insert","text":"z","position":"suffix"}]}"""),
            "ABCz.txt");
    }

    private static void StatusChecks()
    {
        Console.WriteLine("-- status --");

        Check("invalid: empty", PlanBuilder.InvalidReason("") is not null, true);
        Check("invalid: 256 chars", PlanBuilder.InvalidReason(new string('x', 256)) is not null, true);
        Check("valid: 255 chars", PlanBuilder.InvalidReason(new string('x', 255)) is null, true);
        Check("invalid: illegal char", PlanBuilder.InvalidReason("a?b.txt") is not null, true);
        Check("invalid: control char", PlanBuilder.InvalidReason("ab.txt") is not null, true);
        Check("invalid: reserved device name", PlanBuilder.InvalidReason("Com4.log") is not null, true);
        Check("valid: reserved-like name", PlanBuilder.InvalidReason("com10.log") is null, true);

        var dir = NewTempDir();
        try
        {
            foreach (var n in new[] { "one.txt", "two.txt", "three.txt", "existing.txt" })
            {
                File.WriteAllText(Path.Combine(dir, n), "x");
            }

            // one/two both become same.txt; three takes an existing name; existing.txt is untouched.
            var plan = PlanBuilder.Build(dir, Rules("""
                {"steps":[
                  {"op":"replace","find":"^(one|two)$","replaceWith":"same","regex":true},
                  {"op":"replace","find":"three","replaceWith":"existing"}
                ]}
                """));

            string StatusOf(string original) =>
                plan.Items.First(i => i.Original == original).Status.Wire();

            Check("collision: sibling duplicates", StatusOf("one.txt"), "collision");
            Check("collision: existing file", StatusOf("three.txt"), "collision");
            Check("collision beats unchanged", StatusOf("existing.txt"), "collision");

            var untouched = PlanBuilder.Build(dir, Rules("""{"steps":[]}"""));
            Check("unchanged when no steps", untouched.Items.All(i => i.Status == PlanStatus.Unchanged), true);
            Check("directories are excluded", untouched.Items.Count, 4);

            Directory.CreateDirectory(Path.Combine(dir, "child"));
            File.WriteAllText(Path.Combine(dir, "child", "deep.txt"), "x");
            var nonRecursive = PlanBuilder.Build(dir, Rules("""{"steps":[]}"""));
            Check("scan is non-recursive", nonRecursive.Items.Count, 4);
        }
        finally
        {
            Directory.Delete(dir, true);
        }
    }

    private static void SortAndSequenceChecks()
    {
        Console.WriteLine("-- ordering --");

        var dir = NewTempDir();
        try
        {
            foreach (var n in new[] { "b.txt", "A.txt", "a.txt", "_x.txt" })
            {
                File.WriteAllText(Path.Combine(dir, n), "x");
            }

            var plan = PlanBuilder.Build(dir, Rules("""
                {"sort":"name","steps":[{"op":"sequence","pattern":"{n:00}_","start":1,"step":1,"position":"prefix"}]}
                """));

            Check(
                "sort: ordinal, case-sensitive",
                string.Join(",", plan.Items.Select(i => i.Original)),
                "A.txt,_x.txt,a.txt,b.txt");
            Check(
                "sequence follows processing order",
                string.Join(",", plan.Items.Select(i => i.Proposed)),
                "01_A.txt,02__x.txt,03_a.txt,04_b.txt");

            // The counter must advance across a file whose result is invalid.
            var withInvalid = PlanBuilder.Build(dir, Rules("""
                {"sort":"name","steps":[
                  {"op":"replace","find":"_x","replaceWith":"?"},
                  {"op":"sequence","pattern":"{n:0}-","start":1,"step":1,"position":"prefix"}
                ]}
                """));
            Check(
                "sequence advances over an invalid item",
                string.Join(",", withInvalid.Items.Select(i => i.Proposed)),
                "1-A.txt,2-?.txt,3-a.txt,4-b.txt");
        }
        finally
        {
            Directory.Delete(dir, true);
        }
    }

    private static void PlanFileChecks()
    {
        Console.WriteLine("-- plan.json --");

        var dir = NewTempDir();
        try
        {
            File.WriteAllText(Path.Combine(dir, "a.txt"), "x");
            var plan = PlanBuilder.Build(dir, Rules("""
                {"steps":[{"op":"sequence","pattern":"{n:000}_","start":1,"step":1,"position":"prefix"}]}
                """));

            var bytes = PlanWriter.SerializeUtf8(plan);
            var hasBom = bytes.Length >= 3 && bytes[0] == 0xEF && bytes[1] == 0xBB && bytes[2] == 0xBF;
            Check("no UTF-8 BOM", hasBom, false);

            var again = PlanWriter.SerializeUtf8(PlanBuilder.Build(dir, Rules("""
                {"steps":[{"op":"sequence","pattern":"{n:000}_","start":1,"step":1,"position":"prefix"}]}
                """)));
            Check("byte-identical across runs", bytes.SequenceEqual(again), true);

            var text = Encoding.UTF8.GetString(bytes);
            Check("schemaVersion present", text.Contains("\"schemaVersion\": 1"), true);
            Check("proposed name", plan.Items[0].Proposed, "001_a.txt");
            Check("summary total", plan.Summary.Total, 1);
        }
        finally
        {
            Directory.Delete(dir, true);
        }
